return ['domain'=>'lotalytics-lottery-results','plural-forms'=>'nplurals=2; plural=(n != 1);','language'=>'it_IT','project-id-version'=>'Lotalytics – Lottery Results 0.1.0','pot-creation-date'=>'2026-10-17T01:52:44+00:00','po-revision-date'=>'2026-10-17T01:52:44+00:00','messages'=>['Lotalytics – Lottery Results'=>'Lotalytics – Risultati del lotto','Show the latest lottery results and the next draw date for 50+ lotteries, as blocks, a shortcode or a widget. Results come from the Lotalytics API.'=>'Mostra gli ultimi risultati e la data della prossima estrazione di oltre 50 lotterie, come blocchi, shortcode o widget. I risultati provengono dall’API di Lotalytics.','The Lotalytics API answered HTTP %d.'=>'L’API di Lotalytics ha risposto HTTP %d.','Settings'=>'Impostazioni','Game'=>'Gioco','Number of draws'=>'Numero di estrazioni','Compact (hide the next draw date)'=>'Compatto (nasconde la data della prossima estrazione)','Show the title'=>'Mostra il titolo','The game list could not be loaded. Type a game slug, for example "powerball".'=>'Non è stato possibile caricare l’elenco dei giochi. Scrivi lo slug di un gioco, ad esempio "powerball".','Game slug'=>'Slug del gioco','%s results by Lotalytics'=>'Risultati %s da Lotalytics','Lottery results are unavailable right now. Check the game in the block settings, or try again in a few minutes.'=>'I risultati non sono disponibili in questo momento. Controlla il gioco nelle impostazioni del blocco o riprova tra qualche minuto.','Lotalytics Lottery Results'=>'Risultati del lotto Lotalytics','Credit link'=>'Link di attribuzione','Default game'=>'Gioco predefinito','Styling'=>'Stile','Show "Results by Lotalytics" under the results'=>'Mostra "Risultati da Lotalytics" sotto i risultati','Off unless you turn it on. The free Lotalytics service asks sites that use it to show this credit; see the terms linked below.'=>'Disattivato finché non lo attivi. Il servizio gratuito di Lotalytics chiede ai siti che lo usano di mostrare questa attribuzione; vedi i termini collegati qui sotto.','The game list could not be loaded. Enter a game slug, for example "powerball".'=>'Non è stato possibile caricare l’elenco dei giochi. Inserisci lo slug di un gioco, ad esempio "powerball".','Disable the plugin stylesheet'=>'Disattiva il foglio di stile del plugin','For themes that style the results themselves. The markup uses ltc- class names.'=>'Per i temi che stilizzano i risultati da soli. Il markup usa classi ltc-.','Cache cleared.'=>'Cache svuotata.','Add the "Lottery results" or "Next lottery draw" block to any page, or use a shortcode:'=>'Aggiungi il blocco "Risultati del lotto" o "Prossima estrazione" a qualsiasi pagina, oppure usa uno shortcode:','Clear cached results'=>'Svuota i risultati in cache','About the data'=>'Informazioni sui dati','This plugin is a front end for the Lotalytics service. Your server requests results from api.lotalytics.com and caches them; your visitors\' browsers never contact Lotalytics. Each request sends the game, the number of draws, the page language and your site\'s address. Nothing about your visitors is sent.'=>'Questo plugin è un’interfaccia del servizio Lotalytics. Il tuo server richiede i risultati ad api.lotalytics.com e li mette in cache; i browser dei tuoi visitatori non contattano mai Lotalytics. Ogni richiesta invia il gioco, il numero di estrazioni, la lingua della pagina e l’indirizzo del tuo sito. Non viene inviato nulla sui tuoi visitatori.','Terms of service'=>'Termini di servizio','Privacy policy'=>'Informativa sulla privacy','You are not allowed to do that.'=>'Non hai il permesso di farlo.','Lotalytics API'=>'API di Lotalytics','Lottery results can be loaded from Lotalytics'=>'I risultati del lotto possono essere caricati da Lotalytics','Lottery results could not be loaded from Lotalytics'=>'Non è stato possibile caricare i risultati del lotto da Lotalytics','The plugin reached api.lotalytics.com. Results are cached, and the last good copy is shown if the service is briefly unavailable.'=>'Il plugin ha raggiunto api.lotalytics.com. I risultati sono in cache e, se il servizio non è disponibile per poco, viene mostrata l’ultima copia valida.','The game list came back empty.'=>'L’elenco dei giochi è arrivato vuoto.','Lottery results (Lotalytics)'=>'Risultati del lotto (Lotalytics)','The latest winning numbers of a lottery.'=>'Gli ultimi numeri vincenti di una lotteria.','Title (optional)'=>'Titolo (facoltativo)','Bonus'=>'Extra','%s results'=>'Risultati %s','Winning numbers'=>'Numeri vincenti','Next draw: %s'=>'Prossima estrazione: %s','Next %s draw'=>'Prossima estrazione %s','block titleLottery results'=>'Risultati del lotto','block descriptionThe latest winning numbers of a lottery, with the next draw date.'=>'Gli ultimi numeri vincenti di una lotteria, con la data della prossima estrazione.','block keywordlottery'=>'lotteria','block keywordlotto'=>'lotto','block keywordresults'=>'risultati','block keywordwinning numbers'=>'numeri vincenti','block keywordpowerball'=>'powerball','block titleNext lottery draw'=>'Prossima estrazione del lotto','block descriptionThe date of a lottery\'s next scheduled draw.'=>'La data della prossima estrazione prevista di una lotteria.','block keywordnext draw'=>'prossima estrazione','block keywordjackpot'=>'jackpot']];